'use strict';

function compareText(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function buildCollectionView(title, records) {
  if (typeof title !== 'string') {
    throw new TypeError('title must be a string');
  }
  if (!Array.isArray(records)) {
    throw new TypeError('records must be an array');
  }

  const seen = new Set();
  records.forEach((record) => {
    if (record === null || typeof record !== 'object' || Array.isArray(record)) {
      throw new TypeError('each record must be an object');
    }
    if (typeof record.id !== 'string' || record.id.length === 0 ||
        typeof record.label !== 'string' ||
        typeof record.rank !== 'number' || !Number.isFinite(record.rank)) {
      throw new TypeError('record fields are invalid');
    }
    if (seen.has(record.id)) {
      throw new RangeError('record ids must be unique');
    }
    seen.add(record.id);
  });

  records.sort((a, b) =>
    a.rank - b.rank || compareText(a.label, b.label) || compareText(a.id, b.id)
  );
  const items = records.map((record) => ({
    id: record.id,
    label: record.label,
    rank: record.rank
  }));

  return { heading: title.trim(), count: items.length, items };
}

module.exports = { buildCollectionView };

