'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['buildCollectionView']);
const { buildCollectionView } = api;

assert.throws(() => buildCollectionView(4, []), TypeError);
assert.throws(() => buildCollectionView('x', null), TypeError);
assert.deepStrictEqual(buildCollectionView('  Empty  ', []), { heading: 'Empty', count: 0, items: [] });

for (const record of [
  null,
  [],
  { id: 'a', label: 'A' },
  { id: 1, label: 'A', rank: 1 },
  { id: 'a', label: 2, rank: 1 },
  { id: 'a', label: 'A', rank: NaN },
  { id: 'a', label: 'A', rank: Infinity },
  { id: '', label: 'A', rank: 1 }
]) {
  assert.throws(() => buildCollectionView('x', [record]), TypeError);
}
assert.throws(() => buildCollectionView('x', [
  { id: 'same', label: 'A', rank: 1 },
  { id: 'same', label: 'B', rank: 2 }
]), RangeError);

const records = [
  { id: 'z', label: 'Beta', rank: 2 },
  { id: 'b', label: 'alpha', rank: 1 },
  { id: 'a', label: 'alpha', rank: 1 },
  { id: 'c', label: 'Alpha', rank: 1 }
];
const orderBefore = records.map((record) => record.id);
const view = buildCollectionView('  Catalog  ', records);
assert.deepStrictEqual(records.map((record) => record.id), orderBefore);
assert.deepStrictEqual(view, {
  heading: 'Catalog',
  count: 4,
  items: [
    { id: 'c', label: 'Alpha', rank: 1 },
    { id: 'a', label: 'alpha', rank: 1 },
    { id: 'b', label: 'alpha', rank: 1 },
    { id: 'z', label: 'Beta', rank: 2 }
  ]
});
for (let index = 0; index < records.length; index += 1) {
  assert.notStrictEqual(view.items.find((item) => item.id === records[index].id), records[index]);
}
records[0].label = 'changed';
records[1].rank = -100;
records.push({ id: 'new', label: 'New', rank: 0 });
assert.equal(view.count, 4);
assert.deepStrictEqual(view.items.map((item) => item.id), ['c', 'a', 'b', 'z']);
assert.equal(view.items[3].label, 'Beta');

